        audit.record("PERSON_UNRETIRED sheet=" + person.sheetId() + " by=" + unretirement.by() + " name=" + person.name()
                + " on=" + past.get(past.size() - 1).to());
        rollup.record(person.sheetId(), unretirement.by(), before);
    }
}
